'use client'

import { cn } from '@gentleduck/libs/cn'
import { loadDomAnimation } from '@gentleduck/motion/motion-features'
import { useMotionPreset } from '@gentleduck/motion/motion-presets'
import { scaleIn } from '@gentleduck/motion/presets/scale-in'
import { springBouncy } from '@gentleduck/motion/transitions/springs'
import { useDirection } from '@gentleduck/primitives/direction'
import { Lock, LockOpen, Minus, Plus, RotateCcw } from 'lucide-react'
import { LazyMotion, m } from 'motion/react'
import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { MotionBadge } from '../badge'
import { MotionButton } from '../button'
import { MotionButtonGroup } from '../button-group'
import { toDirection } from '../direction/direction.libs'
import { MotionSeparator } from '../separator'
import { MotionTooltip, MotionTooltipContent, TooltipProvider, TooltipTrigger } from '../tooltip'
import type { IPreviewPanelProps } from './preview-panel.types'

const ZOOM_STEP_BUTTON = 0.25
const ZOOM_STEP_WHEEL = 0.1
const MOTION_PREVIEW_PANEL_OPTIONS = { transition: springBouncy } as const
const CONTENT_STYLE = { transformOrigin: 'center center' } as const

function clamp(value: number, min: number, max: number) {
  return Math.max(min, Math.min(max, value))
}

const MotionZoomControls = memo(function MotionZoomControls({
  onZoomIn,
  onZoomOut,
  onReset,
  zoom,
  onToggleLock,
  locked = false,
  zoomInText = 'Zoom in',
  zoomOutText = 'Zoom out',
  resetText = 'Reset view',
  lockText = 'Lock the view',
  unlockText = 'Unlock the view',
}: {
  onZoomIn: () => void
  onZoomOut: () => void
  onReset: () => void
  zoom: number
  onToggleLock?: () => void
  locked?: boolean
  zoomInText?: string
  zoomOutText?: string
  resetText?: string
  lockText?: string
  unlockText?: string
}) {
  return (
    <TooltipProvider>
      <MotionButtonGroup
        data-slot="preview-panel-controls"
        className="rounded-md border bg-background/80 backdrop-blur-sm">
        <MotionTooltip>
          <TooltipTrigger asChild>
            <MotionButton
              variant="ghost"
              size="icon-sm"
              onClick={onZoomIn}
              icon={<Plus aria-hidden="true" />}
              aria-label={zoomInText}
            />
          </TooltipTrigger>
          <MotionTooltipContent>{zoomInText}</MotionTooltipContent>
        </MotionTooltip>
        <MotionSeparator orientation="vertical" />
        <MotionBadge variant="secondary" size="sm" className="rounded-none tabular-nums">
          {Math.round(zoom * 100)}%
        </MotionBadge>
        <MotionSeparator orientation="vertical" />
        <MotionTooltip>
          <TooltipTrigger asChild>
            <MotionButton
              variant="ghost"
              size="icon-sm"
              onClick={onZoomOut}
              icon={<Minus aria-hidden="true" />}
              aria-label={zoomOutText}
            />
          </TooltipTrigger>
          <MotionTooltipContent>{zoomOutText}</MotionTooltipContent>
        </MotionTooltip>
        <MotionSeparator orientation="vertical" />
        <MotionTooltip>
          <TooltipTrigger asChild>
            <MotionButton
              variant="ghost"
              size="icon-sm"
              onClick={onReset}
              icon={<RotateCcw aria-hidden="true" />}
              aria-label={resetText}
            />
          </TooltipTrigger>
          <MotionTooltipContent>{resetText}</MotionTooltipContent>
        </MotionTooltip>
        {onToggleLock && (
          <>
            <MotionSeparator orientation="vertical" />
            <MotionTooltip>
              <TooltipTrigger asChild>
                <MotionButton
                  variant="ghost"
                  size="icon-sm"
                  onClick={onToggleLock}
                  icon={locked ? <Lock aria-hidden="true" /> : <LockOpen aria-hidden="true" />}
                  aria-label={locked ? unlockText : lockText}
                  aria-pressed={locked}
                />
              </TooltipTrigger>
              <MotionTooltipContent>{locked ? unlockText : lockText}</MotionTooltipContent>
            </MotionTooltip>
          </>
        )}
      </MotionButtonGroup>
    </TooltipProvider>
  )
})

const MotionPreviewPanel = React.forwardRef<
  HTMLDivElement,
  Omit<IPreviewPanelProps, 'onDrag' | 'onDragStart' | 'onDragEnd' | 'onAnimationStart'>
>(
  (
    {
      maxHeight,
      minZoom = 0.25,
      maxZoom = 4,
      initialZoom = 1,
      showControls = true,
      defaultLocked = true,
      lockText,
      unlockText,
      actions,
      unsafeHtml,
      children,
      className,
      style,
      onStateChange,
      syncState,
      dir,
      zoomInText,
      zoomOutText,
      resetText,
      ...rest
    },
    ref,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null)
    const contentRef = useRef<HTMLDivElement>(null)
    const content = useMotionPreset(scaleIn, MOTION_PREVIEW_PANEL_OPTIONS)

    const s = useRef({
      zoom: initialZoom,
      x: 0,
      y: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      posStartX: 0,
      posStartY: 0,
      rafId: 0,
      emitPending: false,
      pinchDist: 0,
      pinchZoom: initialZoom,
      willChangeTimer: 0,
    })

    const [displayZoom, setDisplayZoom] = useState(initialZoom)
    const [locked, setLocked] = useState(defaultLocked)
    const toggleLock = useCallback(() => setLocked((was) => !was), [])

    // Ref-shadow so a toggle never re-subscribes the gesture listeners
    const lockedRef = useRef(locked)
    lockedRef.current = locked
    const onStateChangeRef = useRef(onStateChange)
    onStateChangeRef.current = onStateChange

    const flushEmit = useCallback(() => {
      if (!s.current.emitPending) return
      s.current.emitPending = false
      onStateChangeRef.current?.({ zoom: s.current.zoom, x: s.current.x, y: s.current.y })
    }, [])

    const markDirty = useCallback(() => {
      s.current.emitPending = true
    }, [])

    const applyTransform = useCallback((animate: boolean) => {
      const el = contentRef.current
      if (!el) return
      const { x, y, zoom } = s.current
      el.style.transform = `translate3d(${x}px,${y}px,0) scale(${zoom})`
      el.style.transition = animate ? 'transform 0.15s ease-out' : 'none'
      el.style.willChange = 'transform'
      clearTimeout(s.current.willChangeTimer)
      s.current.willChangeTimer = window.setTimeout(() => {
        if (contentRef.current && !s.current.dragging) {
          contentRef.current.style.willChange = 'auto'
        }
      }, 200)
    }, [])

    const scheduleApply = useCallback(() => {
      if (s.current.rafId) return
      s.current.rafId = requestAnimationFrame(() => {
        s.current.rafId = 0
        applyTransform(false)
        flushEmit()
      })
    }, [applyTransform, flushEmit])

    const syncDisplay = useCallback(() => setDisplayZoom(s.current.zoom), [])

    useEffect(() => {
      if (!syncState) return
      const { zoom, x, y } = syncState
      if (Math.abs(s.current.zoom - zoom) < 0.001 && Math.abs(s.current.x - x) < 0.5 && Math.abs(s.current.y - y) < 0.5)
        return
      s.current.zoom = zoom
      s.current.x = x
      s.current.y = y
      applyTransform(true)
      syncDisplay()
    }, [syncState, applyTransform, syncDisplay])

    const handleZoomIn = useCallback(() => {
      s.current.zoom = clamp(s.current.zoom + ZOOM_STEP_BUTTON, minZoom, maxZoom)
      applyTransform(true)
      syncDisplay()
      markDirty()
      flushEmit()
    }, [applyTransform, syncDisplay, markDirty, flushEmit, minZoom, maxZoom])

    const handleZoomOut = useCallback(() => {
      s.current.zoom = clamp(s.current.zoom - ZOOM_STEP_BUTTON, minZoom, maxZoom)
      applyTransform(true)
      syncDisplay()
      markDirty()
      flushEmit()
    }, [applyTransform, syncDisplay, markDirty, flushEmit, minZoom, maxZoom])

    const handleReset = useCallback(() => {
      s.current.zoom = initialZoom
      s.current.x = 0
      s.current.y = 0
      applyTransform(true)
      syncDisplay()
      markDirty()
      flushEmit()
    }, [applyTransform, syncDisplay, markDirty, flushEmit, initialZoom])

    useEffect(() => {
      const el = containerRef.current
      if (!el) return
      const onDown = (e: PointerEvent) => {
        if (lockedRef.current || e.button !== 0) return
        if ((e.target as HTMLElement).closest('[data-slot="preview-panel-toolbar"]')) return
        e.preventDefault()
        el.setPointerCapture(e.pointerId)
        s.current.dragging = true
        s.current.dragStartX = e.clientX
        s.current.dragStartY = e.clientY
        s.current.posStartX = s.current.x
        s.current.posStartY = s.current.y
        el.style.cursor = 'grabbing'
      }
      const onMove = (e: PointerEvent) => {
        if (!s.current.dragging) return
        s.current.x = s.current.posStartX + (e.clientX - s.current.dragStartX)
        s.current.y = s.current.posStartY + (e.clientY - s.current.dragStartY)
        markDirty()
        scheduleApply()
      }
      const onUp = (e: PointerEvent) => {
        if (!s.current.dragging) return
        s.current.dragging = false
        el.releasePointerCapture(e.pointerId)
        el.style.cursor = 'grab'
      }
      const onLeave = () => {
        if (!s.current.dragging) return
        s.current.dragging = false
        el.style.cursor = 'grab'
      }
      el.addEventListener('pointerdown', onDown)
      el.addEventListener('pointermove', onMove)
      el.addEventListener('pointerup', onUp)
      el.addEventListener('pointerleave', onLeave)
      return () => {
        el.removeEventListener('pointerdown', onDown)
        el.removeEventListener('pointermove', onMove)
        el.removeEventListener('pointerup', onUp)
        el.removeEventListener('pointerleave', onLeave)
      }
    }, [markDirty, scheduleApply])

    useEffect(() => {
      const el = containerRef.current
      if (!el) return
      const onWheel = (e: WheelEvent) => {
        if (lockedRef.current) return
        e.preventDefault()
        e.stopPropagation()
        const delta = e.deltaY > 0 ? -ZOOM_STEP_WHEEL : ZOOM_STEP_WHEEL
        s.current.zoom = clamp(s.current.zoom + delta, minZoom, maxZoom)
        markDirty()
        scheduleApply()
        syncDisplay()
      }
      el.addEventListener('wheel', onWheel, { passive: false })
      return () => el.removeEventListener('wheel', onWheel)
    }, [markDirty, scheduleApply, syncDisplay, minZoom, maxZoom])

    useEffect(() => {
      const el = containerRef.current
      if (!el) return
      const dist = (e: TouchEvent) => {
        const a = e.touches[0] ?? { clientX: 0, clientY: 0 }
        const b = e.touches[1] ?? { clientX: 0, clientY: 0 }
        return Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY)
      }
      const onTouchStart = (e: TouchEvent) => {
        if (!lockedRef.current && e.touches.length === 2) {
          e.preventDefault()
          s.current.pinchDist = dist(e)
          s.current.pinchZoom = s.current.zoom
        }
      }
      const onTouchMove = (e: TouchEvent) => {
        if (!lockedRef.current && e.touches.length === 2) {
          e.preventDefault()
          const scale = dist(e) / s.current.pinchDist
          s.current.zoom = clamp(s.current.pinchZoom * scale, minZoom, maxZoom)
          markDirty()
          scheduleApply()
          syncDisplay()
        }
      }
      el.addEventListener('touchstart', onTouchStart, { passive: false })
      el.addEventListener('touchmove', onTouchMove, { passive: false })
      return () => {
        el.removeEventListener('touchstart', onTouchStart)
        el.removeEventListener('touchmove', onTouchMove)
      }
    }, [markDirty, scheduleApply, syncDisplay, minZoom, maxZoom])

    useEffect(() => {
      return () => {
        if (s.current.rafId) cancelAnimationFrame(s.current.rafId)
        clearTimeout(s.current.willChangeTimer)
      }
    }, [])

    const containerStyle = useMemo(
      () => ({ maxHeight, cursor: locked ? 'default' : 'grab', touchAction: locked ? 'auto' : 'none' }) as const,
      [maxHeight, locked],
    )
    const direction = useDirection(toDirection(dir))

    return (
      <LazyMotion features={loadDomAnimation}>
        <m.div
          ref={ref}
          data-slot="preview-panel"
          className={cn('relative flex flex-col', className)}
          dir={direction}
          style={style}
          initial={content.initial}
          animate={content.animate}
          transition={content.transition}
          {...rest}>
          {(showControls || actions) && (
            <div className="absolute end-3 top-3 z-10 flex items-center gap-2" data-slot="preview-panel-toolbar">
              {actions}
              {showControls && (
                <MotionZoomControls
                  lockText={lockText}
                  locked={locked}
                  onReset={handleReset}
                  onToggleLock={toggleLock}
                  onZoomIn={handleZoomIn}
                  onZoomOut={handleZoomOut}
                  resetText={resetText}
                  unlockText={unlockText}
                  zoom={displayZoom}
                  zoomInText={zoomInText}
                  zoomOutText={zoomOutText}
                />
              )}
            </div>
          )}
          <div
            ref={containerRef}
            className="flex flex-1 items-center justify-center overflow-hidden"
            style={containerStyle}>
            {/* SEC-002: `unsafeHtml` is rendered verbatim and is the caller's responsibility to sanitise. */}
            {unsafeHtml !== undefined ? (
              <div
                ref={contentRef}
                className="flex w-full items-center justify-center p-6"
                style={CONTENT_STYLE}
                // biome-ignore lint/security/noDangerouslySetInnerHtml: caller-owns-sanitisation contract documented on `unsafeHtml` prop
                dangerouslySetInnerHTML={{ __html: unsafeHtml }}
              />
            ) : (
              <div ref={contentRef} className="flex w-full items-center justify-center p-6" style={CONTENT_STYLE}>
                {children}
              </div>
            )}
          </div>
        </m.div>
      </LazyMotion>
    )
  },
)
MotionPreviewPanel.displayName = 'MotionPreviewPanel'

export { MotionPreviewPanel, MotionZoomControls }

'use client'

import { cn } from '@gentleduck/libs/cn'
import { Maximize2 } from 'lucide-react'
import React, { useCallback, useMemo, useRef, useState } from 'react'
import { Button } from '../button'
import { Dialog, DialogContent, DialogTrigger } from '../dialog'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '../tooltip'
import { PreviewPanel } from './preview-panel'
import type { IPreviewPanelDialogProps, IPreviewPanelState } from './preview-panel.types'

const PreviewPanelDialog = React.forwardRef<HTMLDivElement, IPreviewPanelDialogProps & { fullscreenText?: string }>(
  (
    {
      children,
      unsafeHtml,
      className,
      panelClassName,
      maxHeight,
      minZoom = 0.25,
      maxZoom = 4,
      initialZoom = 1,
      showControls = true,
      defaultLocked = true,
      lockText,
      unlockText,
      syncPanels = true,
      fullscreenText = 'Open fullscreen',
      zoomInText,
      zoomOutText,
      resetText,
    },
    ref,
  ) => {
    const [sharedState, setSharedState] = useState<IPreviewPanelState | undefined>(undefined)

    // Coalesces simultaneous emissions from both panels into one setState/frame
    const pendingRef = useRef(false)

    const handleStateChange = useCallback(
      (state: IPreviewPanelState) => {
        if (!syncPanels) return
        if (pendingRef.current) return
        pendingRef.current = true
        requestAnimationFrame(() => {
          pendingRef.current = false
          setSharedState(state)
        })
      },
      [syncPanels],
    )

    const contentProps = useMemo(
      () => (unsafeHtml !== undefined ? { unsafeHtml } : { children }),
      [unsafeHtml, children],
    )

    const dialogPanelClassName = useMemo(() => cn('min-h-[70vh]', panelClassName), [panelClassName])

    return (
      <div ref={ref} className={cn('group relative', className)}>
        <TooltipProvider>
          <Dialog>
            <div className="relative overflow-hidden rounded-lg border bg-card">
              <PreviewPanel
                {...contentProps}
                maxHeight={maxHeight}
                minZoom={minZoom}
                maxZoom={maxZoom}
                initialZoom={initialZoom}
                showControls={showControls}
                defaultLocked={defaultLocked}
                lockText={lockText}
                unlockText={unlockText}
                className={panelClassName}
                onStateChange={handleStateChange}
                resetText={resetText}
                syncState={syncPanels ? sharedState : undefined}
                zoomInText={zoomInText}
                zoomOutText={zoomOutText}
                actions={
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <DialogTrigger asChild>
                        <Button
                          variant="ghost"
                          size="icon-sm"
                          icon={<Maximize2 aria-hidden="true" />}
                          aria-label={fullscreenText}
                          className="rounded-md border bg-background/80 backdrop-blur-sm"
                        />
                      </DialogTrigger>
                    </TooltipTrigger>
                    <TooltipContent>{fullscreenText}</TooltipContent>
                  </Tooltip>
                }
              />
            </div>
            <DialogContent className="max-h-[85vh] max-w-[90vw] overflow-auto p-0">
              <PreviewPanel
                {...contentProps}
                minZoom={minZoom}
                maxZoom={maxZoom}
                initialZoom={initialZoom}
                showControls={showControls}
                defaultLocked={false}
                lockText={lockText}
                unlockText={unlockText}
                className={dialogPanelClassName}
                onStateChange={handleStateChange}
                resetText={resetText}
                syncState={syncPanels ? sharedState : undefined}
                zoomInText={zoomInText}
                zoomOutText={zoomOutText}
              />
            </DialogContent>
          </Dialog>
        </TooltipProvider>
      </div>
    )
  },
)
PreviewPanelDialog.displayName = 'PreviewPanelDialog'

export { PreviewPanelDialog }

'use client'

import { cn } from '@gentleduck/libs/cn'
import { useDirection } from '@gentleduck/primitives/direction'
import { Lock, LockOpen, Minus, Plus, RotateCcw } from 'lucide-react'
import React, { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Badge } from '../badge'
import { Button } from '../button'
import { ButtonGroup } from '../button-group'
import { toDirection } from '../direction/direction.libs'
import { Separator } from '../separator'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '../tooltip'
import type { IPreviewPanelProps } from './preview-panel.types'

const ZOOM_STEP_BUTTON = 0.25
const ZOOM_STEP_WHEEL = 0.1

const CONTENT_STYLE = { transformOrigin: 'center center' } as const

function clamp(value: number, min: number, max: number) {
  return Math.max(min, Math.min(max, value))
}

const ZoomControls = memo(function ZoomControls({
  onZoomIn,
  onZoomOut,
  onReset,
  zoom,
  onToggleLock,
  locked = false,
  zoomInText = 'Zoom in',
  zoomOutText = 'Zoom out',
  resetText = 'Reset view',
  lockText = 'Lock the view',
  unlockText = 'Unlock the view',
}: {
  onZoomIn: () => void
  onZoomOut: () => void
  onReset: () => void
  zoom: number
  onToggleLock?: () => void
  locked?: boolean
  zoomInText?: string
  zoomOutText?: string
  resetText?: string
  lockText?: string
  unlockText?: string
}) {
  return (
    <TooltipProvider>
      <ButtonGroup data-slot="preview-panel-controls" className="rounded-md border bg-background/80 backdrop-blur-sm">
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon-sm"
              onClick={onZoomIn}
              icon={<Plus aria-hidden="true" />}
              aria-label={zoomInText}
            />
          </TooltipTrigger>
          <TooltipContent>{zoomInText}</TooltipContent>
        </Tooltip>
        <Separator orientation="vertical" />
        <Badge variant="secondary" size="sm" className="rounded-none tabular-nums">
          {Math.round(zoom * 100)}%
        </Badge>
        <Separator orientation="vertical" />
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon-sm"
              onClick={onZoomOut}
              icon={<Minus aria-hidden="true" />}
              aria-label={zoomOutText}
            />
          </TooltipTrigger>
          <TooltipContent>{zoomOutText}</TooltipContent>
        </Tooltip>
        <Separator orientation="vertical" />
        <Tooltip>
          <TooltipTrigger asChild>
            <Button
              variant="ghost"
              size="icon-sm"
              onClick={onReset}
              icon={<RotateCcw aria-hidden="true" />}
              aria-label={resetText}
            />
          </TooltipTrigger>
          <TooltipContent>{resetText}</TooltipContent>
        </Tooltip>
        {onToggleLock && (
          <>
            <Separator orientation="vertical" />
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  variant="ghost"
                  size="icon-sm"
                  onClick={onToggleLock}
                  icon={locked ? <Lock aria-hidden="true" /> : <LockOpen aria-hidden="true" />}
                  aria-label={locked ? unlockText : lockText}
                  aria-pressed={locked}
                />
              </TooltipTrigger>
              <TooltipContent>{locked ? unlockText : lockText}</TooltipContent>
            </Tooltip>
          </>
        )}
      </ButtonGroup>
    </TooltipProvider>
  )
})

/**
 * Pan-zoom container. Transforms bypass React via direct DOM writes so
 * continuous interactions (drag, wheel, pinch) cause zero re-renders.
 */
const PreviewPanel = React.forwardRef<HTMLDivElement, IPreviewPanelProps>(
  (
    {
      maxHeight,
      minZoom = 0.25,
      maxZoom = 4,
      initialZoom = 1,
      showControls = true,
      defaultLocked = true,
      lockText,
      unlockText,
      actions,
      unsafeHtml,
      children,
      className,
      style,
      onStateChange,
      syncState,
      dir,
      zoomInText,
      zoomOutText,
      resetText,
      ...rest
    },
    ref,
  ) => {
    const containerRef = useRef<HTMLDivElement>(null)
    const contentRef = useRef<HTMLDivElement>(null)

    // Mutable interaction state; nothing in this ref triggers re-renders
    const s = useRef({
      zoom: initialZoom,
      x: 0,
      y: 0,
      dragging: false,
      dragStartX: 0,
      dragStartY: 0,
      posStartX: 0,
      posStartY: 0,
      rafId: 0,
      emitPending: false,
      pinchDist: 0,
      pinchZoom: initialZoom,
      willChangeTimer: 0,
    })

    // The only React state: the zoom label percentage and the lock
    const [displayZoom, setDisplayZoom] = useState(initialZoom)
    const [locked, setLocked] = useState(defaultLocked)
    const toggleLock = useCallback(() => setLocked((was) => !was), [])

    // Ref-shadow so a toggle never re-subscribes the gesture listeners
    const lockedRef = useRef(locked)
    lockedRef.current = locked

    // Ref-shadow so effects never re-subscribe when the callback identity changes
    const onStateChangeRef = useRef(onStateChange)
    onStateChangeRef.current = onStateChange

    const flushEmit = useCallback(() => {
      if (!s.current.emitPending) return
      s.current.emitPending = false
      onStateChangeRef.current?.({
        zoom: s.current.zoom,
        x: s.current.x,
        y: s.current.y,
      })
    }, [])

    // Defer emission to RAF so continuous events batch into one update/frame
    const markDirty = useCallback(() => {
      s.current.emitPending = true
    }, [])

    const applyTransform = useCallback((animate: boolean) => {
      const el = contentRef.current
      if (!el) return
      const { x, y, zoom } = s.current
      el.style.transform = `translate3d(${x}px,${y}px,0) scale(${zoom})`
      el.style.transition = animate ? 'transform 0.15s ease-out' : 'none'
      // GPU-composite during interaction; clear afterwards so the browser
      // re-rasterizes at the final zoom for crisp SVG text
      el.style.willChange = 'transform'
      clearTimeout(s.current.willChangeTimer)
      s.current.willChangeTimer = window.setTimeout(() => {
        if (contentRef.current && !s.current.dragging) {
          contentRef.current.style.willChange = 'auto'
        }
      }, 200)
    }, [])

    // Coalesce DOM writes (and a pending emit) into a single RAF tick
    const scheduleApply = useCallback(() => {
      if (s.current.rafId) return
      s.current.rafId = requestAnimationFrame(() => {
        s.current.rafId = 0
        applyTransform(false)
        flushEmit()
      })
    }, [applyTransform, flushEmit])

    const syncDisplay = useCallback(() => setDisplayZoom(s.current.zoom), [])

    // Receive state from a paired panel
    useEffect(() => {
      if (!syncState) return
      const { zoom, x, y } = syncState
      // Epsilon guard avoids ping-pong when our own emission echoes back
      if (Math.abs(s.current.zoom - zoom) < 0.001 && Math.abs(s.current.x - x) < 0.5 && Math.abs(s.current.y - y) < 0.5)
        return
      s.current.zoom = zoom
      s.current.x = x
      s.current.y = y
      applyTransform(true)
      syncDisplay()
    }, [syncState, applyTransform, syncDisplay])

    // Discrete button handlers emit immediately rather than via RAF
    const handleZoomIn = useCallback(() => {
      s.current.zoom = clamp(s.current.zoom + ZOOM_STEP_BUTTON, minZoom, maxZoom)
      applyTransform(true)
      syncDisplay()
      markDirty()
      flushEmit()
    }, [applyTransform, syncDisplay, markDirty, flushEmit, minZoom, maxZoom])

    const handleZoomOut = useCallback(() => {
      s.current.zoom = clamp(s.current.zoom - ZOOM_STEP_BUTTON, minZoom, maxZoom)
      applyTransform(true)
      syncDisplay()
      markDirty()
      flushEmit()
    }, [applyTransform, syncDisplay, markDirty, flushEmit, minZoom, maxZoom])

    const handleReset = useCallback(() => {
      s.current.zoom = initialZoom
      s.current.x = 0
      s.current.y = 0
      applyTransform(true)
      syncDisplay()
      markDirty()
      flushEmit()
    }, [applyTransform, syncDisplay, markDirty, flushEmit, initialZoom])

    useEffect(() => {
      const el = containerRef.current
      if (!el) return

      const onDown = (e: PointerEvent) => {
        if (lockedRef.current || e.button !== 0) return
        if ((e.target as HTMLElement).closest('[data-slot="preview-panel-toolbar"]')) return
        e.preventDefault()
        el.setPointerCapture(e.pointerId)
        s.current.dragging = true
        s.current.dragStartX = e.clientX
        s.current.dragStartY = e.clientY
        s.current.posStartX = s.current.x
        s.current.posStartY = s.current.y
        el.style.cursor = 'grabbing'
      }

      const onMove = (e: PointerEvent) => {
        if (!s.current.dragging) return
        s.current.x = s.current.posStartX + (e.clientX - s.current.dragStartX)
        s.current.y = s.current.posStartY + (e.clientY - s.current.dragStartY)
        markDirty()
        scheduleApply()
      }

      const onUp = (e: PointerEvent) => {
        if (!s.current.dragging) return
        s.current.dragging = false
        el.releasePointerCapture(e.pointerId)
        el.style.cursor = 'grab'
      }

      const onLeave = () => {
        if (!s.current.dragging) return
        s.current.dragging = false
        el.style.cursor = 'grab'
      }

      el.addEventListener('pointerdown', onDown)
      el.addEventListener('pointermove', onMove)
      el.addEventListener('pointerup', onUp)
      el.addEventListener('pointerleave', onLeave)
      return () => {
        el.removeEventListener('pointerdown', onDown)
        el.removeEventListener('pointermove', onMove)
        el.removeEventListener('pointerup', onUp)
        el.removeEventListener('pointerleave', onLeave)
      }
    }, [markDirty, scheduleApply])

    // Wheel zoom — needs passive:false to preventDefault the page scroll
    useEffect(() => {
      const el = containerRef.current
      if (!el) return

      const onWheel = (e: WheelEvent) => {
        if (lockedRef.current) return
        e.preventDefault()
        e.stopPropagation()
        const delta = e.deltaY > 0 ? -ZOOM_STEP_WHEEL : ZOOM_STEP_WHEEL
        s.current.zoom = clamp(s.current.zoom + delta, minZoom, maxZoom)
        markDirty()
        scheduleApply()
        syncDisplay()
      }

      el.addEventListener('wheel', onWheel, { passive: false })
      return () => el.removeEventListener('wheel', onWheel)
    }, [markDirty, scheduleApply, syncDisplay, minZoom, maxZoom])

    useEffect(() => {
      const el = containerRef.current
      if (!el) return

      const dist = (e: TouchEvent) => {
        const a = e.touches[0] ?? { clientX: 0, clientY: 0 }
        const b = e.touches[1] ?? { clientX: 0, clientY: 0 }
        return Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY)
      }

      const onTouchStart = (e: TouchEvent) => {
        if (!lockedRef.current && e.touches.length === 2) {
          e.preventDefault()
          s.current.pinchDist = dist(e)
          s.current.pinchZoom = s.current.zoom
        }
      }

      const onTouchMove = (e: TouchEvent) => {
        if (!lockedRef.current && e.touches.length === 2) {
          e.preventDefault()
          const scale = dist(e) / s.current.pinchDist
          s.current.zoom = clamp(s.current.pinchZoom * scale, minZoom, maxZoom)
          markDirty()
          scheduleApply()
          syncDisplay()
        }
      }

      el.addEventListener('touchstart', onTouchStart, { passive: false })
      el.addEventListener('touchmove', onTouchMove, { passive: false })
      return () => {
        el.removeEventListener('touchstart', onTouchStart)
        el.removeEventListener('touchmove', onTouchMove)
      }
    }, [markDirty, scheduleApply, syncDisplay, minZoom, maxZoom])

    useEffect(() => {
      return () => {
        if (s.current.rafId) cancelAnimationFrame(s.current.rafId)
        clearTimeout(s.current.willChangeTimer)
      }
    }, [])

    // Dev-only: warn (don't throw) when `unsafeHtml` contains obvious XSS
    // markers. Production builds skip the scan so prop-drilling sanitised
    // build-time HTML stays zero-cost.
    if (IS_DEV && unsafeHtml) {
      warnOnSuspiciousUnsafeHtml(unsafeHtml)
    }

    const containerStyle = useMemo(
      () => ({ maxHeight, cursor: locked ? 'default' : 'grab', touchAction: locked ? 'auto' : 'none' }) as const,
      [maxHeight, locked],
    )
    const direction = useDirection(toDirection(dir))

    return (
      <div
        ref={ref}
        data-slot="preview-panel"
        className={cn('relative flex flex-col', className)}
        dir={direction}
        style={style}
        {...rest}>
        {(showControls || actions) && (
          <div className="absolute end-3 top-3 z-10 flex items-center gap-2" data-slot="preview-panel-toolbar">
            {actions}
            {showControls && (
              <ZoomControls
                lockText={lockText}
                locked={locked}
                onReset={handleReset}
                onToggleLock={toggleLock}
                onZoomIn={handleZoomIn}
                onZoomOut={handleZoomOut}
                resetText={resetText}
                unlockText={unlockText}
                zoom={displayZoom}
                zoomInText={zoomInText}
                zoomOutText={zoomOutText}
              />
            )}
          </div>
        )}
        <div
          ref={containerRef}
          className="flex flex-1 items-center justify-center overflow-hidden"
          style={containerStyle}>
          {/* SEC-002: `unsafeHtml` is rendered verbatim and is the caller's responsibility to sanitise. */}
          {unsafeHtml !== undefined ? (
            <div
              ref={contentRef}
              className="flex w-full items-center justify-center p-6"
              style={CONTENT_STYLE}
              // biome-ignore lint/security/noDangerouslySetInnerHtml: caller-owns-sanitisation contract documented on `unsafeHtml` prop
              dangerouslySetInnerHTML={{ __html: unsafeHtml }}
            />
          ) : (
            <div ref={contentRef} className="flex w-full items-center justify-center p-6" style={CONTENT_STYLE}>
              {children}
            </div>
          )}
        </div>
      </div>
    )
  },
)
PreviewPanel.displayName = 'PreviewPanel'

const SUSPICIOUS_HTML_PATTERN = /<script\b|on\w+\s*=/i
let didWarnUnsafeHtml = false

declare const process: { env?: { NODE_ENV?: string } } | undefined

/** Inlined `__DEV__`-style flag. Dead-code-eliminated by bundlers when `process.env.NODE_ENV === 'production'`. */
const IS_DEV: boolean = typeof process !== 'undefined' && process?.env?.NODE_ENV !== 'production'

/**
 * Dev-only sentinel that warns once per session if `unsafeHtml` looks like
 * it might contain a `<script>` tag or an inline event handler. Not a
 * sanitiser — the prop's contract is still caller-owns-sanitisation.
 */
function warnOnSuspiciousUnsafeHtml(html: string): void {
  if (didWarnUnsafeHtml) return
  if (!SUSPICIOUS_HTML_PATTERN.test(html)) return
  didWarnUnsafeHtml = true
  // eslint-disable-next-line no-console
  console.warn(
    '[PreviewPanel] `unsafeHtml` contains a <script> tag or an inline event handler. ' +
      'This prop is rendered without sanitisation; you MUST only pass markup you fully trust. ' +
      'For untrusted content, pass React children instead.',
  )
}

export { PreviewPanel, ZoomControls }

import type React from 'react'

export interface IPreviewPanelState {
  zoom: number
  x: number
  y: number
}
export type PreviewPanelState = IPreviewPanelState

export interface IPreviewPanelProps extends React.HTMLProps<HTMLDivElement> {
  /** Maximum height of the panel container. */
  maxHeight?: string
  /** Minimum zoom level. Default 0.25. */
  minZoom?: number
  /** Maximum zoom level. Default 4. */
  maxZoom?: number
  /** Initial zoom level. Default 1. */
  initialZoom?: number
  /** Whether to show zoom controls. Default true. */
  showControls?: boolean
  /**
   * Whether drag, wheel and pinch start locked, so the wheel scrolls the page the panel sits in.
   * The zoom buttons work either way. Default true.
   */
  defaultLocked?: boolean
  /** Label for the lock control while the view is unlocked. Default 'Lock the view'. */
  lockText?: string
  /** Label for the lock control while the view is locked. Default 'Unlock the view'. */
  unlockText?: string
  /** Rendered in the toolbar before the zoom controls. */
  actions?: React.ReactNode
  /**
   * Raw HTML string rendered verbatim via `dangerouslySetInnerHTML`. Takes
   * priority over children.
   *
   * SECURITY: this value is NOT sanitised. The caller MUST pass only HTML it
   * fully trusts (e.g. a build-time constant). Never wire user-, CMS-, or
   * URL-derived markup into this prop — doing so is an XSS sink. Pass React
   * `children` instead for untrusted content.
   */
  unsafeHtml?: string
  /** Called whenever zoom or position changes. Use to sync with another panel. */
  onStateChange?: (state: IPreviewPanelState) => void
  /** External state to apply. When set, the panel syncs to this state. */
  syncState?: IPreviewPanelState
  /** Label for the zoom-in control. Default 'Zoom in'. */
  zoomInText?: string
  /** Label for the zoom-out control. Default 'Zoom out'. */
  zoomOutText?: string
  /** Label for the reset control. Default 'Reset view'. */
  resetText?: string
}

export interface IPreviewPanelDialogProps {
  /** Content to render in both the inline panel and the dialog panel. */
  children?: React.ReactNode
  /**
   * Raw HTML string rendered verbatim via `dangerouslySetInnerHTML`. Takes
   * priority over children.
   *
   * SECURITY: this value is NOT sanitised. The caller MUST pass only HTML it
   * fully trusts. Never wire untrusted markup into this prop.
   */
  unsafeHtml?: string
  /** Class name for the inline panel wrapper. */
  className?: string
  /** Class name applied to both PreviewPanel instances. */
  panelClassName?: string
  /** Maximum height of the inline panel. */
  maxHeight?: string
  /** Minimum zoom level. Default 0.25. */
  minZoom?: number
  /** Maximum zoom level. Default 4. */
  maxZoom?: number
  /** Initial zoom level. Default 1. */
  initialZoom?: number
  /** Whether to show zoom controls. Default true. */
  showControls?: boolean
  /** Whether the inline panel starts locked. The fullscreen panel starts unlocked. Default true. */
  defaultLocked?: boolean
  /** Label for the lock control while the view is unlocked. Default 'Lock the view'. */
  lockText?: string
  /** Label for the lock control while the view is locked. Default 'Unlock the view'. */
  unlockText?: string
  /** Whether to sync zoom and position between inline and dialog panels. Default true. */
  syncPanels?: boolean
  /** Label for the zoom-in control. Default 'Zoom in'. */
  zoomInText?: string
  /** Label for the zoom-out control. Default 'Zoom out'. */
  zoomOutText?: string
  /** Label for the reset control. Default 'Reset view'. */
  resetText?: string
}
